shell_commands:
cat > /tmp/ajv-test.js << 'EOF'
import Ajv from 'ajv';
const ajv = new Ajv({format: false, allErrors: true});
const schema = {
  type: 'object',
  properties: {location: {type: 'string'}},
  required: ['location'],
};
const validate = ajv.compile(schema);
const result = validate({});
console.log('Valid:', result);
console.log('Errors:', JSON.stringify(validate.errors, null, 2));

const result2 = validate({location: 123});
console.log('Valid2:', result2);
console.log('Errors2:', JSON.stringify(validate.errors, null, 2));
EOF
node /tmp/ajv-test.js

